#include <iostream>
#include <vector>
#include <cmath>
#include <cstdlib>
using namespace std;

vector<int> memo(10000000, 0);

int solve(long long n) {
    if (n == 0) return 0;
    if (n < memo.size() && memo[n]) return memo[n];

    long long best = 1e18;
    long long rep = 1;
    int steps = 0;
    // generate repunits until distance starts increasing
    for (long long x = 1; ; x = x * 10 + 1, steps++) {
        long long diff = abs(x - n);
        if (diff > best) break;
        best = diff;
        rep = x;
    }
    // rep is the last repunit that gave non-increasing diff
    // but we need the one that gave the minimum diff, which is rep
    // However, the original loop stops when diff > lastdif, so rep is the one before the increase.
    // Actually the loop above: we set best = diff, then update rep = x, then next iteration computes new diff.
    // If new diff > best, we break, so rep is the previous x. That matches original.
    // But we need to adjust steps: steps is incremented after each generation, so after break, steps is the count of repunits generated including the one that caused break? Let's simulate: start steps=0, x=1, diff=abs(1-n), best=diff, rep=1, steps becomes 1, x=11, diff=abs(11-n), if diff>best break, so rep=1, steps=1. That matches original where i=1 after first iteration? Original: i=0 initially, then loop: lastdif=abs(x-n), x=x*10+1, i++. So after first iteration, i=1, x=11. Then if diff>lastdif break, so x=11 is not used, we divide by 10 to get 1. So steps=1 corresponds to i=1, and rep=1. So we need to use steps-1? Actually original uses i after loop, then x/=10. So i is the number of times we multiplied, which is steps. Then x/=10 gives the repunit that gave the minimum diff. So we have rep = x/10? In our loop, rep is the last repunit that gave non-increasing diff, which is the one before the increase. That is exactly x/10. So we can use rep directly. But steps is the count after the loop, which is the number of repunits generated including the one that caused break. So the number of digits of rep is steps-1? Actually rep = 1 has 1 digit, steps=1? Let's test n=10: loop: steps=0, x=1, diff=9, best=9, rep=1, steps=1, x=11, diff=1, best=1, rep=11, steps=2, x=111, diff=101, >best break. So rep=11, steps=2. Original: i=2 after loop, x=111, then x/=10 => 11, i=2. So steps corresponds to i. So we can use steps as i. But we need to consider that rep is the one that gave minimum diff, which is the last repunit before the increase. So we have rep and steps. Then we proceed as original.

    if (rep > n && rep / 10) {
        long long prev = rep / 10;
        return memo[n] = min(steps + solve(abs(rep - n)), steps - 1 + solve(abs(prev - n)));
    }
    return memo[n] = steps + solve(abs(rep - n));
}

int main() {
#ifdef NEKROLM
    freopen("input.txt", "r", stdin);
    freopen("output.txt", "w", stdout);
#endif
    ios_base::sync_with_stdio(false);
    long long n;
    cin >> n;
    cout << solve(n);
    return 0;
}
